squieu, o poder deve ser dividido em:","opcoes":["Executivo, Legislativo e Judiciário","Rei, Igreja e povo","Federal, estadual e municipal, sem divisão de funções","Civil e militar"],"explicacao":"Teoria da separação dos poderes."},{"id":3730,"materia":"fil","nivel":2,"enunciado":"Segundo o conceito de 'alienação' em Marx, o trabalhador:","opcoes":["Não se reconhece no produto do próprio trabalho","Controla todo o processo produtivo, do início ao fim","É dono dos meios de produção","Trabalha por prazer"],"explicacao":"O produto pertence ao capitalista."},{"id":3731,"materia":"fil","nivel":3,"enunciado":"Para John Locke, todo ser humano tem direitos naturais como:","opcoes":["Vida, liberdade e propriedade","Poder absoluto e títulos de nobreza","Escravizar outros povos","Isenção de leis"],"explicacao":"O governo existe para protegê-los."},{"id":3732,"materia":"fil","nivel":3,"enunciado":"Para Nietzsche, a ideia de 'Deus está morto' indica:","opcoes":["A crise dos valores tradicionais na modernidade","O fim da humanidade","Uma prova científica","A volta da religião medieval e da autoridade da Igreja"],"explicacao":"Propõe a criação de novos valores."},{"id":3733,"materia":"fil","nivel":4,"enunciado":"Simone de Beauvoir afirmou que 'ninguém nasce mulher, torna-se mulher', defendendo que:","opcoes":["Os papéis de gênero são construídos socialmente","O gênero é definido apenas pela biologia","As mulheres não devem estudar","Não há desigualdade entre homens e mulheres na sociedade moderna"],"explicacao":"Obra: O Segundo Sexo (1949)."},{"id":3734,"materia":"mat","nivel":2,"enunciado":"Um terreno quadrado tem 400 m² de área. A medida do lado é:","opcoes":["20 m","40 m","100 m","200 m"],"explicacao":"Lado = raiz quadrada de 400."},{"id":3735,"materia":"mat","nivel":3,"enunciado":"Um carro faz 12 km por litro. Para rodar 300 km, com a gasolina a R$ 6,00 o litro, gasta-se:","opcoes":["R$ 150,00","R$ 25,00","R$ 180,00","R$ 72,00"],"explicacao":"300 ÷ 12 = 25 litros; 25 × 6 = 150."},{"id":3736,"materia":"mat","nivel":4,"enunciado":"Um reservatório cilíndrico tem raio 2 m e altura 5 m. Usando π = 3, seu volume é:","opcoes":["60 m³","30 m³","20 m³","120 m³"],"explicacao":"V = π · r² · h = 3 × 4 × 5."},{"id":3737,"materia":"mat","nivel":1,"enunciado":"Em um mapa, 1 cm equivale a 5 km. Duas cidades que estão a 7 cm no mapa ficam, na realidade, a:","opcoes":["35 km","12 km","7 km","70 km"],"explicacao":"7 × 5 = 35 km."},{"id":3738,"materia":"bio","nivel":2,"enunciado":"O DNA é formado por unidades chamadas:","opcoes":["Nucleotídeos","Aminoácidos","Ácidos graxos","Monossacarídeos"],"explicacao":"Cada nucleotídeo tem açúcar, fosfato e base nitrogenada."}]$q$::jsonb)
  as x(id integer, materia text, nivel smallint, enunciado text, opcoes jsonb, explicacao text)
on conflict (id) do update set materia = excluded.materia, nivel = excluded.nivel, enunciado = excluded.enunciado, opcoes = excluded.opcoes, explicacao = excluded.explicacao;

select setval(pg_get_serial_sequence('public.questoes', 'id'), (select max(id) from public.questoes));
select materia, count(*) as questoes from public.questoes where materia in ('ling','mat','fis','qui','bio','his','geo','fil') group by materia order by materia;
select count(*) as total_de_questoes from public.questoes;
